{"CommandLine":"python -c "
import os, sys, ast, py_compile, json

roots = [r'C:\AI-BS', r'C:\AI-BS-Models', r'C:\StehouwerPublishing.com']
ignore_dirs = {'.git', 'node_modules', '__pycache__', '.venv', 'venv', '.gemini'}

results = []

for root in roots:
    if not os.path.exists(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in ignore_dirs]
        for f in filenames:
            if f.endswith('.py'):
                full_path = os.path.join(dirpath, f)
                rel_path = os.path.relpath(full_path, root)
                file_size = os.path.getsize(full_path)

                status = 'OK'
                syntax_err = None
                broken_paths = []
                imports = []

                if file_size == 0:
                    status = 'EMPTY'
                else:
                    try:
                        with open(full_path, 'r', encoding='utf-8', errors='ignore') as fp:
                            code = fp.read()

                        tree = ast.parse(code, filename=full_path)

                        # Inspect string literals for file path health
                        for node in ast.walk(tree):
                            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                                val = node.value
                                # check if string looks like absolute path
                                if (len(val) > 3 and val[1] == ':' and val[2] in ('\\', '/')):
                                    # Normalize Windows path
                                    norm_path = os.path.normpath(val)
                                    if not os.path.exists(norm_path):
                                        broken_paths.append(val)
                            elif isinstance(node, (ast.Import, ast.ImportFrom)):
                                if isinstance(node, ast.Import):
                                    for alias in node.names:
                                        imports.append(alias.name)
                                elif isinstance(node, ast.ImportFrom) and node.module:
                                    imports.append(node.module)
                    except SyntaxError as se:
                        status = 'SYNTAX_ERROR'
                        syntax_err = f'Line {se.lineno}: {se.msg}'
                    except Exception as e:
                        status = 'PARSE_ERROR'
                        syntax_err = str(e)

                is_archive = '_archive' in full_path.lower() or 'quarantine' in full_path.lower() or 'scratch' in full_path.lower()

                results.append({
                    'root': root,
                    'file': full_path,
                    'rel_file': rel_path,
                    'size': file_size,
                    'status': status,
                    'syntax_err': syntax_err,
                    'broken_paths': broken_paths,
                    'is_archive': is_archive
                })

print(f'TOTAL_SCANNED: {len(results)}')
syntax_errors = [r for r in results if r['status'] in ('SYNTAX_ERROR', 'PARSE_ERROR')]
empty_files = [r for r in results if r['status'] == 'EMPTY']
broken_path_files = [r for r in results if r['broken_paths']]
active_files = [r for r in results if not r['is_archive']]

print(f'ACTIVE_FILES_COUNT: {len(active_files)}')
print(f'ARCHIVED_FILES_COUNT: {len(results) - len(active_files)}')
print(f'SYNTAX_ERRORS_COUNT: {len(syntax_errors)}')
print(f'EMPTY_FILES_COUNT: {len(empty_files)}')
print(f'BROKEN_PATHS_COUNT: {len(broken_path_files)}')

with open(r'C:\AI-BS\py_health_audit.json', 'w', encoding='utf-8') as out:
    json.dump({'summary': {'total': len(results), 'active': len(active_files), 'archive': len(results)-len(active_files), 'syntax_errors': len(syntax_errors), 'empty': len(empty_files), 'broken_path_files': len(broken_path_files)}, 'details': results}, out, indent=2)

print('Audit written to C:\\AI-BS\\py_health_audit.json')
